const limits = {
  1: 10,
  10: 30,
  30: 60,
  60: 100
};

const intervals = {
  1: 60000,      // 1 minute
  10: 600000,    // 10 minutes
  30: 1800000,   // 30 minutes
  60: 3600000    // 60 minutes
};
const now = Date.now();
let userRate = $input.first().json;

// --- Reset windows individually ---
for (const key of ["1","10","30","60"]) {
  if (now - userRate[`lastTime${key}`] > intervals[key]) {
    userRate[`count${key}`] = 0;
    userRate[`lastTime${key}`] = now;
  }
}


// --- Check limits in ascending severity ---
if (userRate.count60 >= limits[60]) {
  return [{ json: { ...userRate, error: "⚠️ Too many messages in the past hour. Please wait before sending more.", status: 429 } }];
}
if (userRate.count30 >= limits[30]) {
  return [{ json: { ...userRate, error: "⚠️ You've sent too many messages in 30 minutes. Take a short break.", status: 429 } }];
}
if (userRate.count10 >= limits[10]) {
  return [{ json: { ...userRate, error: "⚠️ You've hit the 10-minute limit. Try again soon.", status: 429 } }];
}
if (userRate.count1 >= limits[1]) {
  return [{ json: { ...userRate, error: "⚠️ Slow down — too many messages in a minute.", status: 429 } }];
}

// --- Increment counts ---
for (const key of ["1","10","30","60"]) {
  userRate[`count${key}`]++;
  userRate[`lastTime${key}`] = now;
}

// --- Output updated data ---
return [{ json: userRate }];
